<?php require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/auth.php'; if(is_logged_in()){header('Location: '.(($_SESSION['user']['role'] ?? '')==='Maintenance Staff' ? 'maintenance/work_orders.php' : 'dashboard.php'));exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$stmt=$pdo->prepare('SELECT id,name,email,password,role FROM users WHERE email=? AND is_active=1');$stmt->execute([trim($_POST['email']??'')]);$u=$stmt->fetch(PDO::FETCH_ASSOC);if($u&&password_verify($_POST['password']??'',$u['password'])){session_regenerate_id(true);$_SESSION['user']=$u;header('Location: '.(($u['role'] ?? '')==='Maintenance Staff' ? 'maintenance/work_orders.php' : 'dashboard.php'));exit;}$error='Incorrect email or password.';} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in | WareFlow</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="/warehouse-maintenance/assets/css/style.css" rel="stylesheet"></head><body class="login-page"><form class="login-card" method="post"><div class="login-logo mb-2">▣ WAREFLOW</div><h2 class="h4 mb-1">Welcome back</h2><p class="text-muted mb-4">Sign in to manage warehouse maintenance.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif?><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label class="form-label">Email address</label><input class="form-control mb-3" name="email" type="email" required placeholder="you@company.com"><label class="form-label">Password</label><input class="form-control mb-4" name="password" type="password" required placeholder="••••••••"><button class="btn btn-primary w-100 py-2">Sign in</button></form></body></html>
